    ctx.next()?;
    ctx.mes("[Staff]")?;
    ctx.mes(op(op(op(op(s("is "), "+", get(ctx, "@record_min70")?)?, "+", s("minutes "))?, "+", get(ctx, "@record_sec70")?)?, "+", s("seconds."))?.text())?;
    ctx.mes("Congratulations!")?;
    ctx.next()?;
    ctx.mes("[Staff]")?;
    ctx.mes(op(op(s("The fastest player among people who cleared Lv70 arena time force battle is ^3131FF"), "+", get(ctx, "$arena_70topn$")?)?, "+", s("^000000."))?.text())?;
    ctx.next()?;
    ctx.mes("[Staff]")?;
    ctx.mes(op(op(op(op(op(op(s("^3131FF"), "+", get(ctx, "$arena_70topn$")?)?, "+", s("^000000's running time was ^3131FF"))?, "+", get(ctx, "$top_70min")?)?, "+", s("^000000minutes ^3131FF"))?, "+", get(ctx, "$top_70sec")?)?, "+", s("^000000seconds."))?.text())?;
